using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using System.Web.Script.Serialization;
using Microsoft.Win32;
internal static class WatcherWorker {
[DllImport("kernel32.dll",SetLastError=true)] static extern bool GetLogicalProcessorInformationEx(int relation,IntPtr buffer,ref uint length);
[DllImport("kernel32.dll")] static extern ushort GetActiveProcessorGroupCount();
[DllImport("kernel32.dll",SetLastError=true)] static extern bool GetProcessAffinityMask(IntPtr process,out UIntPtr processMask,out UIntPtr systemMask);
[DllImport("kernel32.dll",SetLastError=true)] static extern bool SetProcessAffinityMask(IntPtr process,UIntPtr mask);
[DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
[DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr window,out uint processId);
[StructLayout(LayoutKind.Sequential)] struct NativeTime {public uint low,high;public double Milliseconds {get{return (((ulong)high<<32)|low)/10000.0;}}}
[StructLayout(LayoutKind.Sequential)] struct PowerState {public uint version,controlMask,stateMask;}
[StructLayout(LayoutKind.Sequential)] struct MemoryState {public uint priority;}
[DllImport("kernel32.dll",SetLastError=true)] static extern bool GetSystemTimes(out NativeTime idle,out NativeTime kernel,out NativeTime user);
[DllImport("kernel32.dll",SetLastError=true)] static extern bool GetProcessInformation(IntPtr process,int info,ref PowerState state,uint size);
[DllImport("kernel32.dll",SetLastError=true)] static extern bool SetProcessInformation(IntPtr process,int info,ref PowerState state,uint size);
[DllImport("kernel32.dll",SetLastError=true)] static extern bool GetProcessInformation(IntPtr process,int info,ref MemoryState state,uint size);
[DllImport("kernel32.dll",SetLastError=true)] static extern bool SetProcessInformation(IntPtr process,int info,ref MemoryState state,uint size);
static readonly HashSet<string> Allowed=new HashSet<string>(StringComparer.OrdinalIgnoreCase){"cs2","chrome","msedge","firefox","brave","opera","vivaldi","Discord","Spotify","OneDrive","Dropbox","GoogleDriveFS","steamwebhelper","Slack","Telegram","Teams","ms-teams","obs64"};
static readonly HashSet<string> Levels=new HashSet<string>{"Normal","BelowNormal","AboveNormal"};
static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=524288,RecursionLimit=16};
static readonly int Session=Process.GetCurrentProcess().SessionId;
static string GamePath;
static void Emit(object value){string line=Json.Serialize(value);if(line.Length>524288)throw new Exception("Response exceeds limit");Console.WriteLine(line);Console.Out.Flush();}
static ulong Mask(string value){ulong parsed;if(value.Length>16||!ulong.TryParse(value,NumberStyles.AllowHexSpecifier,CultureInfo.InvariantCulture,out parsed)||parsed==0)throw new Exception("Invalid affinity mask");return parsed;}
static string Hex(ulong value){return value.ToString("x",CultureInfo.InvariantCulture);}
static string S(Dictionary<string,object> r,string key){object value;if(!r.TryGetValue(key,out value)||!(value is string))throw new Exception("Invalid "+key);return (string)value;}
static int Pid(Dictionary<string,object> r){object value;int pid;if(!r.TryGetValue("pid",out value)||!int.TryParse(Convert.ToString(value,CultureInfo.InvariantCulture),out pid)||pid<1)throw new Exception("Invalid PID");return pid;}
static bool Same(string a,string b){return String.Equals(a,b,StringComparison.OrdinalIgnoreCase);}
static void Scope(Process process){if(!Allowed.Contains(process.ProcessName)||process.SessionId!=Session)throw new Exception("Process outside scope");if(Same(process.ProcessName,"cs2")&&(GamePath==null||!Same(process.MainModule.FileName,GamePath)))throw new Exception("CS2 path outside scope");}
static bool Identity(Process p,Dictionary<string,object> r){DateTime expected;if(!DateTime.TryParse(S(r,"startedAt"),CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out expected))throw new Exception("Invalid process start date");return p.StartTime.ToUniversalTime()==expected.ToUniversalTime()&&Same(p.MainModule.FileName,S(r,"path"));}
  static object Topology(){
    uint size=0;GetLogicalProcessorInformationEx(0,IntPtr.Zero,ref size);if(size==0||size>1048576)throw new Exception("Topology unavailable");
    IntPtr buffer=Marshal.AllocHGlobal((int)size);try{
      if(!GetLogicalProcessorInformationEx(0,buffer,ref size))throw new Exception("Topology read failed");
      var cores=new List<object>();uint offset=0;
      while(offset<size){IntPtr record=IntPtr.Add(buffer,(int)offset);uint recordSize=(uint)Marshal.ReadInt32(record,4);if(recordSize<48||offset+recordSize>size)throw new Exception("Invalid topology record");
        int relation=Marshal.ReadInt32(record,0);if(relation==0){byte efficiency=Marshal.ReadByte(record,9);ushort groups=(ushort)Marshal.ReadInt16(record,30);if(groups<1||32+16*groups>recordSize)throw new Exception("Invalid core record");
          for(int i=0;i<groups;i++){int start=32+i*16;ulong mask=unchecked((ulong)Marshal.ReadInt64(record,start));ushort group=(ushort)Marshal.ReadInt16(record,start+8);cores.Add(new {group=group,mask=Hex(mask),efficiencyClass=efficiency});}}
        offset+=recordSize;
      }
      UIntPtr current,system;if(!GetProcessAffinityMask(Process.GetCurrentProcess().Handle,out current,out system))throw new Exception("System mask unavailable");
      return new {supported=GetActiveProcessorGroupCount()==1,groups=GetActiveProcessorGroupCount(),systemMask=Hex(system.ToUInt64()),cores=cores};
    }finally{Marshal.FreeHGlobal(buffer);}
  }

static List<object> Inventory(out List<string> governors,out bool truncated){var rows=new List<object>();var seenGovernors=new HashSet<string>(StringComparer.OrdinalIgnoreCase);object gameRow=null;governors=new List<string>();truncated=false;foreach(Process p in Process.GetProcesses()){using(p){string name;try{name=p.ProcessName;}catch(System.ComponentModel.Win32Exception){continue;}catch(InvalidOperationException){continue;}string known=Same(name,"ProcessLasso")?"ProcessLasso":Same(name,"ProcessGovernor")?"ProcessGovernor":null;if(known!=null&&seenGovernors.Add(known))governors.Add(known);try{if(p.SessionId!=Session)continue;}catch(System.ComponentModel.Win32Exception){continue;}catch(InvalidOperationException){continue;}if(!Allowed.Contains(name))continue;try{string executable=p.MainModule.FileName;if(Same(name,"cs2")&&(GamePath==null||!Same(executable,GamePath)))continue;Scope(p);object row=new {pid=p.Id,name=p.ProcessName,path=executable,startedAt=p.StartTime.ToUniversalTime().ToString("o"),priority=p.PriorityClass.ToString(),memoryMB=Math.Round(p.WorkingSet64/1048576.0),cpuMs=p.TotalProcessorTime.TotalMilliseconds};if(rows.Count<256)rows.Add(row);else truncated=true;if(Same(name,"cs2"))gameRow=row;}catch(System.ComponentModel.Win32Exception){continue;}catch(UnauthorizedAccessException){continue;}catch(InvalidOperationException){continue;}}}if(gameRow!=null&&!rows.Contains(gameRow)){if(rows.Count==256)rows[255]=gameRow;else rows.Add(gameRow);}return rows;}
static object List(){List<string> governors;bool truncated;var rows=Inventory(out governors,out truncated);return new {rows=rows,truncated=truncated,externalGovernor=governors.Count>0,externalGovernorNames=governors};}
static bool GameFocused(){if(GamePath==null)return false;uint pid;GetWindowThreadProcessId(GetForegroundWindow(),out pid);if(pid==0)return false;Process p;try{p=Process.GetProcessById((int)pid);}catch(ArgumentException){return false;}using(p){return Same(p.ProcessName,"cs2")&&p.SessionId==Session&&Same(p.MainModule.FileName,GamePath);}}
static object Sample(){NativeTime idle,kernel,user;if(!GetSystemTimes(out idle,out kernel,out user))throw new Exception("CPU counters unavailable");List<string> governors;bool truncated;var rows=Inventory(out governors,out truncated);return new {supported=GetActiveProcessorGroupCount()==1,logicalProcessors=Environment.ProcessorCount,totalMs=kernel.Milliseconds+user.Milliseconds,idleMs=idle.Milliseconds,gameFocused=GameFocused(),externalGovernor=governors.Count>0,externalGovernorNames=governors,rows=rows,truncated=truncated};}
static uint Bit(Dictionary<string,object> r,string key){object value;uint number;if(!r.TryGetValue(key,out value)||!uint.TryParse(Convert.ToString(value,CultureInfo.InvariantCulture),out number)||number>1)throw new Exception("Invalid power state");return number;}
static object PowerOp(Dictionary<string,object> r,string op){Process p;try{p=Process.GetProcessById(Pid(r));}catch(ArgumentException){return new {status="exited"};}using(p){IntPtr pinned=p.Handle;if(!Identity(p,r))return new {status="replaced"};Scope(p);if(!Same(p.ProcessName,"cs2"))throw new Exception("Power operation outside allowed process scope");PowerState current=new PowerState{version=1};if(!GetProcessInformation(pinned,4,ref current,12))return new {status="unsupported",errorCode=Marshal.GetLastWin32Error()};uint control=current.controlMask&1,state=current.stateMask&1;if(op=="getPower")return new {status="ok",control=control,state=state};uint expectedControl=Bit(r,"expectedControl"),expectedState=Bit(r,"expectedState");if(control!=expectedControl||(control==1&&state!=expectedState))return new {status="conflict"};uint desiredControl=Bit(r,"control"),desiredState=Bit(r,"state");current.version=1;current.controlMask=(current.controlMask&~1u)|desiredControl;current.stateMask=(current.stateMask&~1u)|desiredState;if(!SetProcessInformation(pinned,4,ref current,12))throw new Exception("Power preference write denied");PowerState after=new PowerState{version=1};if(!GetProcessInformation(pinned,4,ref after,12)||(after.controlMask&1)!=desiredControl||(desiredControl==1&&(after.stateMask&1)!=desiredState))throw new Exception("Power preference not confirmed");return new {status="changed"};}}
static uint MemoryPriority(Dictionary<string,object> r,string key){object value;uint number;if(!r.TryGetValue(key,out value)||!uint.TryParse(Convert.ToString(value,CultureInfo.InvariantCulture),out number)||number<1||number>5)throw new Exception("Invalid memory priority");return number;}
static object MemoryOp(Dictionary<string,object> r,string op){Process p;try{p=Process.GetProcessById(Pid(r));}catch(ArgumentException){return new {status="exited"};}using(p){IntPtr pinned=p.Handle;if(!Identity(p,r))return new {status="replaced"};Scope(p);if(Same(p.ProcessName,"cs2"))throw new Exception("Memory priority is limited to selected background processes");MemoryState current=new MemoryState();if(!GetProcessInformation(pinned,0,ref current,4))return new {status="unsupported",errorCode=Marshal.GetLastWin32Error()};if(current.priority<1||current.priority>5)return new {status="unsupported"};if(op=="getMemoryPriority")return new {status="ok",priority=current.priority};uint expected=MemoryPriority(r,"expectedPriority"),desired=MemoryPriority(r,"priority");if(current.priority!=expected)return new {status="conflict"};current.priority=desired;if(!SetProcessInformation(pinned,0,ref current,4))throw new Exception("Memory priority write denied");MemoryState after=new MemoryState();if(!GetProcessInformation(pinned,0,ref after,4)||after.priority!=desired)throw new Exception("Memory priority not confirmed");return new {status="changed"};}}
static bool Running(){if(GamePath==null)throw new Exception("CS2 path unavailable");foreach(Process p in Process.GetProcessesByName("cs2")){using(p){try{if(p.SessionId!=Session)continue;if(!Same(p.MainModule.FileName,GamePath))throw new Exception("CS2 installation changed; restart monitor");return true;}catch(InvalidOperationException){if(!p.HasExited)throw;}}}return false;}
static object Focus(){if(GamePath==null)throw new Exception("CS2 path unavailable");uint pid;GetWindowThreadProcessId(GetForegroundWindow(),out pid);if(pid==0)return new {focused=false};Process p;try{p=Process.GetProcessById((int)pid);}catch(ArgumentException){return new {focused=false};}using(p){if(!Same(p.ProcessName,"cs2")||p.SessionId!=Session)return new {focused=false};return new {focused=Same(p.MainModule.FileName,GamePath)};}}
static object ProcessOp(Dictionary<string,object> r,string op){int pid=Pid(r);Process p;try{p=Process.GetProcessById(pid);}catch(ArgumentException){return new {status="exited"};}using(p){IntPtr pinnedHandle=p.Handle;
if(op=="setPriority"||op=="setAffinity"){if(!Identity(p,r))return new {status="replaced"};if(op=="setPriority"&&!Same(p.ProcessName,S(r,"name")))return new {status="replaced"};}Scope(p);
if(op=="setPriority"){string expected=S(r,"expected"),desired=S(r,"priority");if(!Levels.Contains(expected)||!Levels.Contains(desired))throw new Exception("Invalid priority");object guard;if(r.TryGetValue("backgroundOnly",out guard)){if(!(guard is bool))throw new Exception("Invalid foreground guard");if((bool)guard&&(!GameFocused()||Same(p.ProcessName,"cs2")))return new {status="foreground"};}if(p.PriorityClass.ToString()!=expected)return new {status="conflict"};p.PriorityClass=(ProcessPriorityClass)Enum.Parse(typeof(ProcessPriorityClass),desired);p.Refresh();if(p.PriorityClass.ToString()!=desired)throw new Exception("Priority not confirmed");return new {status="changed"};}
if(GetActiveProcessorGroupCount()!=1)throw new Exception("Multiple processor groups unsupported");UIntPtr current,system;if(!GetProcessAffinityMask(p.Handle,out current,out system))throw new Exception("Affinity read denied");if(op=="getAffinity")return new {status="ok",pid=pid,name=p.ProcessName,path=p.MainModule.FileName,startedAt=p.StartTime.ToUniversalTime().ToString("o"),mask=Hex(current.ToUInt64()),systemMask=Hex(system.ToUInt64())};
ulong expectedMask=Mask(S(r,"expected")),desiredMask=Mask(S(r,"mask"));if(current.ToUInt64()!=expectedMask)return new {status="conflict"};if((desiredMask&system.ToUInt64())!=desiredMask)throw new Exception("Mask exceeds available CPUs");if(!SetProcessAffinityMask(p.Handle,new UIntPtr(desiredMask)))throw new Exception("Affinity write denied");if(!GetProcessAffinityMask(p.Handle,out current,out system)||current.ToUInt64()!=desiredMask)throw new Exception("Affinity not confirmed");return new {status="changed"};}}
static object Operation(Dictionary<string,object> r){string op=S(r,"op");switch(op){case "list":return List();case "sample":return Sample();case "getPower":case "setPower":return PowerOp(r,op);case "getMemoryPriority":case "setMemoryPriority":return MemoryOp(r,op);case "snapshot":return new {running=Running()};case "focused":return Focus();case "topology":return Topology();case "getAffinity":case "setAffinity":case "setPriority":return ProcessOp(r,op);case "steamActiveUser":using(RegistryKey key=Registry.CurrentUser.OpenSubKey(@"Software\Valve\Steam\ActiveProcess")){if(key==null)return 0;object value=key.GetValue("ActiveUser",0,RegistryValueOptions.DoNotExpandEnvironmentNames);if(!(value is int))throw new Exception("Steam ActiveUser is not DWORD");return unchecked((uint)(int)value);}default:throw new Exception("Unknown operation");}}
static string ReadLine(){var line=new StringBuilder();int ch;while((ch=Console.In.Read())!=-1){if(ch==10)return line.ToString();if(ch!=13)line.Append((char)ch);if(line.Length>16384)throw new Exception("Request exceeds limit");}return line.Length==0?null:line.ToString();}
static int Main(string[] args){Console.OutputEncoding=new UTF8Encoding(false);try{if(IntPtr.Size!=8)throw new Exception("Requires x64");if(args.Length!=0){if(args.Length!=2||args[0]!="--game"||!Path.IsPathRooted(args[1])||!Same(Path.GetFileName(args[1]),"cs2.exe"))throw new Exception("Invalid game path");GamePath=Path.GetFullPath(args[1]);}Emit(new {ready=true,version=1});string line;while((line=ReadLine())!=null){long id=0;try{var r=Json.Deserialize<Dictionary<string,object>>(line);object raw;if(!r.TryGetValue("id",out raw)||!long.TryParse(Convert.ToString(raw,CultureInfo.InvariantCulture),out id)||id<1)throw new Exception("Invalid request ID");Emit(new {id=id,ok=true,result=Operation(r)});}catch(Exception error){Emit(new {id=id,ok=false,error=error.Message});}}return 0;}catch(Exception error){Console.Error.WriteLine(error.Message);return 1;}}
}
